mapper.select:
SELECT t.id, t.task_no AS taskNo, t.title, t.type, t.status, t.priority, t.progress, t.project_id AS projectId, t.assignee_id AS assigneeId, t.milestone_id AS milestoneId, t.due_date AS dueDate, t.is_overdue AS isOverdue, t.is_warning AS isWarning, t.comment_count AS commentCount, p.name AS projectName, u.real_name AS assigneeName FROM tsk_task t LEFT JOIN prj_project p ON p.id = t.project_id LEFT JOIN sys_user u ON u.id = t.assignee_id
t.deleted_at IS NULL
AND t.project_id = #{query.projectId}
AND t.phase_id = #{query.phaseId}
AND t.type IN
#{tp}
AND t.status IN
#{st}
AND t.assignee_id = #{query.assigneeId}
AND (t.title ILIKE CONCAT('%', #{query.keyword}, '%') OR t.description ILIKE CONCAT('%', #{query.keyword}, '%'))
AND t.is_overdue = #{query.isOverdue}
AND t.planned_start >= #{query.startDateFrom}
AND t.planned_start <= #{query.startDateTo}
AND t.due_date >= #{query.dueDateFrom}
AND t.due_date <= #{query.dueDateTo}
ORDER BY t.created_at DESC
